: true|false, "DataEncipherment": true|false, "KeyAgreement": true|false, "KeyCertSign": true|false, "CRLSign": true|false, "EncipherOnly": true|false, "DecipherOnly": true|false }, "SubjectInformationAccess": [ { "AccessMethod": { "CustomObjectIdentifier": "string", "AccessMethodType": "CA_REPOSITORY"|"RESOURCE_PKI_MANIFEST"|"RESOURCE_PKI_NOTIFY" }, "AccessLocation": { "OtherName": { "TypeId": "string", "Value": "string" }, "Rfc822Name": "string", "DnsName": "string", "DirectoryName": { "Country": "string", "Organization": "string", "OrganizationalUnit": "string", "DistinguishedNameQualifier": "string", "State": "string", "CommonName": "string", "SerialNumber": "string", "Locality": "string", "Title": "string", "Surname": "string", "GivenName": "string", "Initials": "string", "Pseudonym": "string", "GenerationQualifier": "string", "CustomAttributes": [ { "ObjectIdentifier": "string", "Value": "string" } ... ] }, "EdiPartyName": { "PartyName": "string", "NameAssigner": "string" }, "UniformResourceIdentifier": "string", "IpAddress": "string", "RegisteredId": "string" } } ... ] } }
    /// </summary>
    [CliOption("--certificate-authority-configuration")]
    public string? CertificateAuthorityConfiguration { get; private init; }

    /// <summary>
