    /// </summary>
    [CliOption("--certificate-authority-type")]
    public AwsAcmPcaCreateCertificateAuthorityCertificateAuthorityType? CertificateAuthorityType { get; private init; }

    /// <summary>
    /// Contains information to enable support for Online Certificate Status Protocol (OCSP), certificate revocation list (CRL), both protocols, or neither. By default, both certificate validation mechanisms are disabled. The following requirements apply to revocation configurations. o A configuration disabling CRLs or OCSP must contain only the En- abled=False parameter, and will fail if other parameters such as CustomCname or ExpirationInDays are included. o In a CRL configuration, the S3BucketName parameter must conform to Amazon S3 bucket naming rules . o A configuration containing a custom Canonical Name (CNAME) parame- ter for CRLs or OCSP must conform to RFC2396 restrictions on the use of special characters in a CNAME. o In a CRL or OCSP configuration, the value of a CNAME parameter must not include a protocol prefix such as "http://" or "- https://". For more information, see the OcspConfiguration and CrlConfiguration types. CrlConfiguration -&gt; (structure) Configuration of the certificate revocation list (CRL), if any, maintained by your private CA. A CRL is typically updated ap- proximately 30 minutes after a certificate is revoked. If for any reason a CRL update fails, Amazon Web Services Private CA makes further attempts every 15 minutes. Enabled -&gt; (boolean) [required] Boolean value that specifies whether certificate revocation lists (CRLs) are enabled. You can use this value to enable certificate revocation for a new CA when you call the CreateCertificateAuthority action or for an existing CA when you call the UpdateCertificateAuthority action. ExpirationInDays -&gt; (integer) Validity period of the CRL in days. Constraints: o min: 1 o max: 5000 CustomCname -&gt; (string) Name inserted into the certificate CRL Distribution Points extension that enables the use of an alias for the CRL dis- tribution point. Use this value if you don't want the name of your S3 bucket to be public. NOTE: The content of a Canonical Name (CNAME) record must con- form to RFC2396 restrictions on the use of special char- acters in URIs. Additionally, the value of the CNAME must not include a protocol prefix such as "http://" or "- https://". Constraints: o min: 0 o max: 253 o pattern: [-a-zA-Z0-9;/?:@&amp;=+$,%_.!~*()']* S3BucketName -&gt; (string) Name of the S3 bucket that contains the CRL. If you do not provide a value for the CustomCname argument, the name of your S3 bucket is placed into the CRL Distribution Points ex- tension of the issued certificate. You can change the name of your bucket by calling the UpdateCertificateAuthority opera- tion. You must specify a bucket policy that allows Amazon Web Services Private CA to write the CRL to your bucket. NOTE: The S3BucketName parameter must conform to the S3 bucket naming rules . Constraints: o min: 3 o max: 255 o pattern: [-a-zA-Z0-9._/]+ S3ObjectAcl -&gt; (string) Determines whether the CRL will be publicly readable or pri- vately held in the CRL Amazon S3 bucket. If you choose PUB- LIC_READ, the CRL will be accessible over the public inter- net. If you choose BUCKET_OWNER_FULL_CONTROL, only the owner of the CRL S3 bucket can access the CRL, and your PKI clients may need an alternative method of access. If no value is specified, the default is PUBLIC_READ . Note: This default can cause CA creation to fail in some circumstances. If you have have enabled the Block Public Access (BPA) feature in your S3 account, then you must specify the value of this parameter as BUCKET_OWNER_FULL_CONTROL , and not doing so results in an error. If you have disabled BPA in S3, then you can specify either BUCKET_OWNER_FULL_CONTROL or PUBLIC_READ as the value. For more information, see Blocking public access to the S3 bucket . Possible values: o PUBLIC_READ o BUCKET_OWNER_FULL_CONTROL CrlDistributionPointExtensionConfiguration -&gt; (structure) Configures the behavior of the CRL Distribution Point exten- sion for certificates issued by your certificate authority. If this field is not provided, then the CRl Distribution Point Extension will be present and contain the default CRL URL. OmitExtension -&gt; (boolean) [required] Configures whether the CRL Distribution Point extension should be populated with the default URL to the CRL. If set to true , then the CDP extension will not be present in any certificates issued by that CA unless otherwise specified through CSR or API passthrough. NOTE: Only set this if you have another way to distribute the CRL Distribution Points for certificates issued by your CA, such as the Matter Distributed Compliance Ledger This configuration cannot be enabled with a custom CNAME set. CrlType -&gt; (string) Specifies whether to create a complete or partitioned CRL. This setting determines the maximum number of certificates that the certificate authority can issue and revoke. For more information, see Amazon Web Services Private CA quotas . o COMPLETE - The default setting. Amazon Web Services Private CA maintains a single CRL le for all unexpired certicates issued by a CA that have been revoked for any reason. Each certicate that Amazon Web Services Private CA issues is bound to a specic CRL through its CRL distribution point (CDP) extension, dened in RFC 5280 . o PARTITIONED - Compared to complete CRLs, partitioned CRLs dramatically increase the number of certicates your private CA can issue. WARNING: When using partitioned CRLs, you must validate that the CRL's associated issuing distribution point (IDP) URI matches the certicate's CDP URI to ensure the right CRL has been fetched. Amazon Web Services Private CA marks the IDP extension as critical, which your client must be able to process. Possible values: o COMPLETE o PARTITIONED CustomPath -&gt; (string) Designates a custom le path in S3 for CRL(s). For example, http://&lt;CustomName&gt;/ &lt;CustomPath&gt;/&lt;CrlPartition_GUID&gt;.crl . Constraints: o min: 0 o max: 253 o pattern: (/|[-a-zA-Z0-9;?:@&amp;=+$,%_.!~*()']+(/[-a-zA-Z0-9;?:@&amp;=+$,%_.!~*()']+)*) OcspConfiguration -&gt; (structure) Configuration of Online Certificate Status Protocol (OCSP) sup- port, if any, maintained by your private CA. When you revoke a certificate, OCSP responses may take up to 60 minutes to reflect the new status. Enabled -&gt; (boolean) [required] Flag enabling use of the Online Certificate Status Protocol (OCSP) for validating certificate revocation status. OcspCustomCname -&gt; (string) By default, Amazon Web Services Private CA injects an Amazon Web Services domain into certificates being validated by the Online Certificate Status Protocol (OCSP). A customer can al- ternatively use this object to define a CNAME specifying a customized OCSP domain. NOTE: The content of a Canonical Name (CNAME) record must con- form to RFC2396 restrictions on the use of special char- acters in URIs. Additionally, the value of the CNAME must not include a protocol prefix such as "http://" or "- https://". For more information, see Customizing Online Certificate Sta- tus Protocol (OCSP) in the Amazon Web Services Private Cer- tificate Authority User Guide . Constraints: o min: 0 o max: 253 o pattern: [-a-zA-Z0-9;/?:@&amp;=+$,%_.!~*()']* Shorthand Syntax: CrlConfiguration={Enabled=boolean,ExpirationInDays=integer,CustomCname=string,S3BucketName=string,S3ObjectAcl=string,CrlDistributionPointExtensionConfiguration={OmitExtension=boolean},CrlType=string,CustomPath=string},OcspConfiguration={Enabled=boolean,OcspCustomCname=string} JSON Syntax: { "CrlConfiguration": { "Enabled": true|false, "ExpirationInDays": integer, "CustomCname": "string", "S3BucketName": "string", "S3ObjectAcl": "PUBLIC_READ"|"BUCKET_OWNER_FULL_CONTROL", "CrlDistributionPointExtensionConfiguration": { "OmitExtension": true|false }, "CrlType": "COMPLETE"|"PARTITIONED", "CustomPath": "string" }, "OcspConfiguration": { "Enabled": true|false, "OcspCustomCname": "string" } }
    /// </summary>
    [CliOption("--revocation-configuration")]
    public string? RevocationConfiguration { get; set; }

    /// <summary>
    /// Custom string that can be used to distinguish between calls to the CreateCertificateAuthority action. Idempotency tokens for CreateCer- tificateAuthority time out after five minutes. Therefore, if you call CreateCertificateAuthority multiple times with the same idempo- tency token within five minutes, Amazon Web Services Private CA rec- ognizes that you are requesting only certificate authority and will issue only one. If you change the idempotency token for each call, Amazon Web Services Private CA recognizes that you are requesting multiple certificate authorities. Constraints: o min: 1 o max: 36 o pattern: [\u0009\u000A\u000D\u0020-\u00FF]*
    /// </summary>
    [SecretValue]
    [CliOption("--idempotency-token")]
    public string? IdempotencyToken { get; set; }

    /// <summary>
    /// Specifies a cryptographic key management compliance standard for handling and protecting CA keys. Default: FIPS_140_2_LEVEL_3_OR_HIGHER NOTE: Some Amazon Web Services Regions don't support the default value. When you create a CA in these Regions, you must use CCPC_LEVEL_1_OR_HIGHER for the KeyStorageSecurityStandard para- meter. If you don't, the operation returns an InvalidArgsExcep- tion with this message: "A certificate authority cannot be cre- ated in this region with the specified security standard." For information about security standard support in different Amazon Web Services Regions, see Storage and security compliance of Amazon Web Services Private CA private keys . Possible values: o FIPS_140_2_LEVEL_2_OR_HIGHER o FIPS_140_2_LEVEL_3_OR_HIGHER o CCPC_LEVEL_1_OR_HIGHER
    /// </summary>
    [CliOption("--key-storage-security-standard")]
    public AwsAcmPcaCreateCertificateAuthorityKeyStorageSecurityStandard? KeyStorageSecurityStandard { get; set; }

    /// <summary>
    /// Key-value pairs that will be attached to the new private CA. You can associate up to 50 tags with a private CA. For information using tags with IAM to manage permissions, see Controlling Access Using IAM Tags . Constraints: o min: 1 o max: 50 (structure) Tags are labels that you can use to identify and organize your private CAs. Each tag consists of a key and an optional value. You can associate up to 50 tags with a private CA. To add one or more tags to a private CA, call the TagCertificateAuthority ac- tion. To remove a tag, call the UntagCertificateAuthority ac- tion. Key -&gt; (string) [required] Key (name) of the tag. Constraints: o min: 1 o max: 128 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) Value -&gt; (string) Value of the tag. Constraints: o min: 0 o max: 256 o pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) Shorthand Syntax: Key=string,Value=string ... JSON Syntax: [ { "Key": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// Specifies whether the CA issues general-purpose certificates that typically require a revocation mechanism, or short-lived certifi- cates that may optionally omit revocation because they expire quickly. Short-lived certificate validity is limited to seven days. The default value is GENERAL_PURPOSE. Possible values: o GENERAL_PURPOSE o SHORT_LIVED_CERTIFICATE
    /// </summary>
    [CliOption("--usage-mode")]
    public AwsAcmPcaCreateCertificateAuthorityUsageMode? UsageMode { get; set; }

